export const createDailyEntryBodyManualMandaysMin = 0;

export const createDailyEntryBodyServiceCostsItemMandaysMin = 0;

export const createDailyEntryBodyServiceCostsItemManualMandaysMin = 0;

export const createDailyEntryBodyServiceCostsItemMealQuantitiesItemQtyMin = 0;

export const createDailyEntryBodyServiceCostsItemSubCostsItemCostDefault = 0;
export const createDailyEntryBodyServiceCostsItemSubCostsItemCostMin = 0;

export const createDailyEntryBodyServiceCostsItemSubCostsItemMandaysDefault = 0;
export const createDailyEntryBodyServiceCostsItemSubCostsItemMandaysMin = 0;

export const CreateDailyEntryBody = zod.object({
  entryDate: zod.coerce.date(),
  location: zod.string().min(1),
  totalMandays: zod
    .number()
    .min(createDailyEntryBodyTotalMandaysMin)
    .optional()
    .describe(
      "Only honored when totalMandaysOverride is true; otherwise auto-summed from serviceCosts plus manualMandays.",
    ),
  totalMandaysOverride: zod
    .boolean()
    .default(createDailyEntryBodyTotalMandaysOverrideDefault),
  manualMandays: zod
    .number()
    .min(createDailyEntryBodyManualMandaysMin)
    .default(createDailyEntryBodyManualMandaysDefault)
    .describe(
      "Added on top of auto-summed service mandays. Ignored when totalMandaysOverride is true.",
    ),
  notes: zod.string().optional(),
  serviceCosts: zod.array(
    zod.object({
      projectServiceId: zod.string(),
      kind: zod.enum(["food", "standard", "group"]),
      cost: zod
        .number()
        .optional()
        .describe("Total daily cost for this service line (SAR)"),
      mandays: zod
        .number()
        .min(createDailyEntryBodyServiceCostsItemMandaysMin)
        .optional()
        .describe("Optional per-service mandays contribution"),
      manualMandays: zod
        .number()
        .min(createDailyEntryBodyServiceCostsItemManualMandaysMin)
        .optional()
        .describe(
          "Per-service manual mandays added on top of the auto-computed\n(food formula) mandays. Used by food services to add ad-hoc\nmandays not captured by the meal counts.\n",
        ),
      mealQuantities: zod
        .array(
          zod.object({
            mealItemId: zod
              .string()
              .nullish()
              .describe(
                "The service meal item this quantity is for. Null only when\nediting an entry whose saved meal type has since been removed\nfrom the service — the row is then matched by `name`.\n",
              ),
            name: zod
              .string()
              .optional()
              .describe(
                "Required when mealItemId is null (snapshot row match).",
              ),
            qty: zod
              .number()
              .min(
                createDailyEntryBodyServiceCostsItemMealQuantitiesItemQtyMin,
              ),
          }),
        )
        .optional()
        .describe(
          "Per meal-type quantity rows for kind=food services. On create,\n`mealItemId` must reference one of the service's meal items and\nthe server snapshots its current name + weight. On update, rows\nwhose `mealItemId` matches a previously saved row keep that row's\nsnapshot; rows for meal items deleted since the entry was saved\nare matched by `name`. Mandays for the food line are computed\nserver-side as sum(qty x weight) + manualMandays.\n",
        ),
      subCosts: zod
        .array(
          zod.object({
            subItemId: zod.string(),
            cost: zod
              .number()
              .min(createDailyEntryBodyServiceCostsItemSubCostsItemCostMin)
              .default(
                createDailyEntryBodyServiceCostsItemSubCostsItemCostDefault,
              ),
            mandays: zod
              .number()
              .min(createDailyEntryBodyServiceCostsItemSubCostsItemMandaysMin)
              .default(
                createDailyEntryBodyServiceCostsItemSubCostsItemMandaysDefault,
              ),
          }),
        )
        .optional()
        .describe(
          "Per sub-item cost+mandays rows for kind=group services. Cost and\nmandays for the parent service line are derived as the sum of\nthese rows (plus manualMandays for mandays). Ignored for other kinds.\n",
        ),
    }),
  ),
});

export const GetDailyEntryParams = zod.object({
  id: zod.coerce.string(),
});

export const getDailyEntryResponseOneManualMandaysMin = 0;

export const getDailyEntryResponseOneAttachmentCountMin = 0;

export const getDailyEntryResponseTwoAttachmentsItemFileSizeMin = 0;

export const GetDailyEntryResponse = zod
  .object({
    id: zod.string(),
    projectId: zod.string(),
    projectName: zod.string(),
    entryDate: zod.coerce.date(),
    location: zod.string(),
    totalMandays: zod.number(),
    totalCost: zod.number(),
    costPerManday: zod.number(),
    totalMandaysOverride: zod.boolean(),
    manualMandays: zod
      .number()
      .min(getDailyEntryResponseOneManualMandaysMin)
      .describe(
        "Extra mandays added on top of the auto-summed service mandays. Ignored when totalMandaysOverride is true.",
      ),
    attachmentCount: zod
      .number()
      .min(getDailyEntryResponseOneAttachmentCountMin)
      .describe("Number of files attached to this entry."),
    status: zod
      .enum(["draft", "pending", "approved"])
      .describe(
        "Workflow state. `draft` = created but not yet submitted (won't show\nup in approver queues). `pending` = submitted; advancing through the\napproval chain. `approved` = final approval recorded; entry is locked.\n",
      ),
    currentApprovalLevel: zod.number(),
    isLocked: zod.boolean(),
    lockedAt: zod.coerce.date().nullish(),
    notes: zod.string().nullish(),
    sequenceNumber: zod.number().nullish(),
    sequenceCode: zod.string().nullish(),
  })
  .and(
    zod.object({
      serviceCosts: zod.array(
        zod.object({
          id: zod.string(),
          projectServiceId: zod.string(),
          serviceName: zod.string(),
          kind: zod.enum(["food", "standard", "group"]),
          cost: zod.number(),
          mandays: zod.number().nullish(),
          manualMandays: zod
            .number()
            .optional()
            .describe(
              "Per-service manual mandays added on top of the auto-computed value.",
            ),
          mandayContribution: zod.number(),
          costPerManday: zod.number(),
          mealQuantities: zod
            .array(
              zod.object({
                mealItemId: zod.string().nullable(),
                name: zod.string(),
                weight: zod
                  .number()
                  .describe(
                    "Snapshot weight (fraction) taken when the entry was saved.",
                  ),
                qty: zod.number(),
              }),
            )
            .optional()
            .describe(
              "Per meal-type rows for kind=food; empty for other kinds. Name and\nweight are the snapshot taken when the entry was saved, so they\nstay correct even after the service's meal items are edited or\nremoved (mealItemId becomes null on removal).\n",
            ),
          subCosts: zod
            .array(
              zod.object({
                subItemId: zod.string(),
                subItemName: zod.string(),
                cost: zod.number(),
                mandays: zod.number(),
              }),
            )
            .optional()
            .describe(
              "Per sub-item rows for kind=group; empty for other kinds.",
            ),
        }),
      ),
      attachments: zod.array(
        zod.object({
          id: zod.string(),
          dailyEntryId: zod.string(),
          objectPath: zod
            .string()
            .describe(
              "Normalized path returned by the storage upload endpoint (begins with `\/objects\/...`).",
            ),
          fileName: zod.string(),
          fileSize: zod
            .number()
            .min(getDailyEntryResponseTwoAttachmentsItemFileSizeMin),
          mimeType: zod.string(),
          uploadedById: zod.string().nullish(),
          uploadedAt: zod.coerce.date(),
        }),
      ),
    }),
  );

